function renderHome(){const t=text[lang];main.innerHTML=`<section class="hero"><video muted loop playsinline preload="none" poster="${posterAsset}" aria-hidden="true" tabindex="-1"></video><div class="wrap hero-inner"><div class="hero-composition"><div class="hero-copy"><span class="eyebrow">${t.eyebrow}</span><h1>${t.headline}</h1><p>${t.lead}</p><div class="hero-actions"><a class="btn light" href="#services">${t.explore} ↗</a><a class="glass-link" href="#contact">${t.talk} ↗</a></div></div><aside class="edge-discovery" aria-label="${lang==='tr'?'Etkinlik keşfi':'Explore events'}"><div class="edge-wheel"><div class="edge-orbit" aria-hidden="true"></div><button type="button" class="edge-core" aria-label="${lang==='tr'?'Etkinlikleri keşfedin':'Explore events'}"><span class="core-ripples" aria-hidden="true"><i></i><i></i><i></i></span><svg class="core-arc-label" viewBox="0 0 430 430" aria-hidden="true"><defs><path id="discover-curve" d="M 215 400 A 185 185 0 0 1 215 30"/></defs><text><textPath href="#discover-curve" startOffset="50%" text-anchor="middle">${lang==='tr'?'Keşfedin':'Explore'}</textPath></text></svg></button>${[240,200,160,120].map((angle,i)=>{const r=angle*Math.PI/180;return `<div class="edge-item" style="--px:${Math.cos(r)};--py:${Math.sin(r)};--turn:${angle+90}deg"><button class="edge-petal" type="button" data-edge="${i}" aria-expanded="false" aria-controls="edge-tip-${i}" aria-label="${esc(t.eventTitles[i])}"><span>0${i+1}</span></button><div class="edge-tip" id="edge-tip-${i}" hidden><a href="#event/${i}">${t.eventTitles[i]} <span aria-hidden="true">↗</span></a></div></div>`;}).join('')}</div></aside></div><div class="hero-bottom"><span>${t.footer}</span><div class="video-controls"><span class="status" role="status"></span><button id="videoControl" aria-label="${t.playVideo}" title="${t.playVideo}"><span class="video-symbol is-play" aria-hidden="true"></span></button></div></div></div></section><section class="wrap feature" aria-label="${t.selectSlide}"><div class="slider"><div id="slides">${articles.map((a,i)=>`<a class="slide" href="#article/${a.id}" ${i?'hidden':''}><div class="slide-copy"><span class="eyebrow">${a[lang].tag}</span><h2>${a[lang].title}</h2><p>${a[lang].intro.split('. ')[0]}.</p><span class="read">${t.read} ↗</span></div><div class="slide-visual"><span class="visual-label">${['01 / '+t.serviceNames[2],'02 / '+t.serviceNames[0],'03 / '+t.serviceNames[1]][i]}</span></div></a>`).join('')}</div><div class="slider-controls"><div class="slider-buttons" id="dots">${articles.map((a,i)=>`<button aria-label="${esc(a[lang].title)}" aria-current="${i===0}">${i+1}</button>`).join('')}</div><div class="slider-buttons"><button id="previous" aria-label="${t.prev}">←</button><button id="next" aria-label="${t.next}">→</button><button id="pause">${t.pause}</button></div></div></div></section><section class="wrap" id="numbers" aria-label="${t.about}"><div class="stats">${['2.465','41.675+','370'].map((n,i)=>`<div class="stat"><strong>${lang==='en'?n.replaceAll('.',','):n}</strong><span>${t.statLabels[i]}</span></div>`).join('')}</div></section><section class="section wrap" id="services"><div class="section-top"><div><span class="eyebrow">${t.serviceTag}</span><h2>${t.serviceTitle}</h2></div><p>${t.serviceIntro}</p></div><div class="tabs" role="tablist" aria-label="${t.serviceTag}">${t.serviceNames.map((n,i)=>`<button role="tab" id="tab${i}" aria-controls="servicePanel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-tab="${i}">${n}</button>`).join('')}</div><div id="servicePanel" class="service-panel" role="tabpanel" aria-labelledby="tab0" tabindex="0"></div></section><section class="band" id="events"><div class="wrap section"><div class="section-top"><div><span class="eyebrow">${t.eventsTag}</span><h2>${t.eventsTitle}</h2></div><p>${t.eventsNote}</p></div><div class="event-filters" aria-label="${t.eventsTag}">${t.filterLabels.map((name,i)=>`<button type="button" data-filter="${i}" aria-pressed="${i===0}">${name}</button>`).join('')}</div><div class="event-count" role="status" id="eventCount">6 ${t.eventUnit}</div><div class="event-grid">${t.eventTitles.map((title,i)=>`<details class="event-card" data-kind="${i%2+1}"><summary><div class="event-top"><time class="event-date" datetime="${['2026-10-15','2026-10-22','2026-11-05','2026-11-19','2026-12-03','2026-12-17'][i]}"><b>${['15','22','05','19','03','17'][i]}</b><small>${t.eventDates[i]}</small></time><span class="event-format">${t.eventTypes[i]}</span></div><span class="event-title"><b>${title}</b><small>${t.example}</small></span><div class="event-bottom"><span>${t.detailsLabel}</span><span class="plus" aria-hidden="true">+</span></div></summary><div class="event-body">${t.eventBodies[i]}<p><a class="back" href="#contact">${t.talk} ↗</a></p></div></details>`).join('')}</div></div></section><section class="wrap section" id="insights"><div class="section-top"><div><span class="eyebrow">${t.blogTag}</span><h2>${t.blogTitle}</h2></div><p>${t.blogLead}</p></div><div class="blog-grid">${articles.map(card).join('')}</div></section><section class="wrap" id="contact"><div class="contact"><div><span class="eyebrow">${t.contact}</span><h2>${t.contactTitle}</h2><p>${t.contactLead}</p><p class="note">${t.demo}</p></div><div class="contact-cards"><a class="contact-card" href="tel:+902120000000"><span>${t.phone} ↗</span><strong>+90 (212) 000 00 00</strong></a><a class="contact-card" href="mailto:iletisim@example.com"><span>${t.email} ↗</span><strong>iletisim@example.com</strong></a></div></div></section>`;

const edgeItems=[...document.querySelectorAll('.edge-item')];
function closeEdge(){edgeItems.forEach(item=>{item.classList.remove('is-open');item.querySelector('.edge-tip').hidden=true;item.querySelector('button').setAttribute('aria-expanded','false');});}
function openEdge(index){closeEdge();const item=edgeItems[index];item.classList.add('is-open');item.querySelector('.edge-tip').hidden=false;item.querySelector('button').setAttribute('aria-expanded','true');}
edgeItems.forEach((item,i)=>{let delay;item.addEventListener('pointerenter',e=>{clearTimeout(delay);if(e.pointerType!=='touch')openEdge(i);});item.addEventListener('pointerleave',()=>{delay=setTimeout(()=>{if(!item.contains(document.activeElement)){item.classList.remove('is-open');item.querySelector('.edge-tip').hidden=true;item.querySelector('button').setAttribute('aria-expanded','false');}},180);});item.querySelector('button').addEventListener('click',()=>openEdge(i));item.addEventListener('focusin',()=>{clearTimeout(delay);openEdge(i);});item.addEventListener('focusout',e=>{if(!item.contains(e.relatedTarget))closeEdge();});item.addEventListener('keydown',e=>{if(e.key==='Escape'){closeEdge();item.querySelector('button').focus();closeEdge();}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();edgeItems[(i+(e.key==='ArrowDown'?1:3))%4].querySelector('button').focus();}});});
document.querySelector('.edge-core').onclick=()=>edgeItems[0].querySelector('button').focus();
const filters=[...document.querySelectorAll('[data-filter]')];filters.forEach(button=>button.onclick=()=>{const value=button.dataset.filter;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.event-card').forEach(card=>{card.hidden=value!=='0'&&card.dataset.kind!==value;if(!card.hidden)count++;});document.querySelector('#eventCount').textContent=count+' '+t.eventUnit;});
const tabs=[...document.querySelectorAll('[role=tab]')];function tab(i){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1;});let panel=document.querySelector('#servicePanel');panel.setAttribute('aria-labelledby','tab'+i);panel.innerHTML=`<div><h3>${t.serviceHead[i]}</h3><p>${t.serviceDesc[i]}</p><a class="back" href="#article/${['learning','analysis','export'][i]}">${t.courseMore} ↗</a></div><ul>${t.serviceLists[i].map((x,j)=>`<li><span>0${j+1}</span>${x}</li>`).join('')}</ul>`;}tabs.forEach((b,i)=>{b.onclick=()=>tab(i);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;tab(n);tabs[n].focus();}}});tab(0);
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const slider=document.querySelector('.slider'),slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('#dots button')],pause=document.querySelector('#pause');let index=0,paused=reduced.matches,timer,visible=false;function show(i){index=(i+3)%3;slides.forEach((s,j)=>s.hidden=j!==index);dots.forEach((d,j)=>d.setAttribute('aria-current',String(j===index)));}function schedule(){clearInterval(timer);if(visible&&!paused&&!document.hidden&&!slider.matches(':hover')&&!slider.contains(document.activeElement))timer=setInterval(()=>show(index+1),5000);}function pauseLabel(){pause.textContent=paused?t.play:t.pause;}dots.forEach((d,i)=>d.onclick=()=>{show(i);schedule();});document.querySelector('#previous').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);pause.onclick=()=>{paused=!paused;pauseLabel();schedule();};slider.onmouseenter=()=>clearInterval(timer);slider.onmouseleave=schedule;slider.onfocusin=()=>clearInterval(timer);slider.onfocusout=()=>setTimeout(schedule,0);pauseLabel();let observer;if('IntersectionObserver'in window){observer=new IntersectionObserver(e=>{visible=e[0].isIntersecting;schedule();},{threshold:.2});observer.observe(slider);}else{visible=true;schedule();}
const video=document.querySelector('video'),vc=document.querySelector('#videoControl');
const mobile=window.matchMedia('(max-width: 767px)');let userPaused=reduced.matches,inside=false,disposed=false;
function syncVideo(){const permitted=inside&&!document.hidden&&!mobile.matches&&!userPaused&&!disposed;
if(permitted){if(!video.getAttribute('src'))video.src=videoAsset;video.play().catch(()=>{});}else video.pause();
vc.hidden=mobile.matches;vc.setAttribute('aria-label',video.paused?t.playVideo:t.pauseVideo);vc.title=video.paused?t.playVideo:t.pauseVideo;vc.innerHTML='<span class="video-symbol '+(video.paused?'is-play':'is-pause')+'" aria-hidden="true"></span>';}
vc.onclick=()=>{userPaused=!userPaused;syncVideo();};video.onplay=()=>{if(disposed||!inside||document.hidden||mobile.matches)video.pause();else{vc.innerHTML='<span class="video-symbol is-pause" aria-hidden="true"></span>';vc.setAttribute('aria-label',t.pauseVideo);}};
video.onpause=()=>{vc.innerHTML='<span class="video-symbol is-play" aria-hidden="true"></span>';vc.setAttribute('aria-label',t.playVideo);};
const videoObserver=new IntersectionObserver(entries=>{inside=entries[0].isIntersecting;syncVideo();},{threshold:0});videoObserver.observe(video);
function visibility(){schedule();syncVideo();}function motion(e){if(e.matches){userPaused=true;paused=true;pauseLabel();schedule();}syncVideo();}function deviceChange(){syncVideo();if(mobile.matches){video.removeAttribute('src');video.load();}}
document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',motion);mobile.addEventListener('change',deviceChange);syncVideo();
cleanup=()=>{disposed=true;clearInterval(timer);observer?.disconnect();videoObserver.disconnect();document.removeEventListener('visibilitychange',visibility);reduced.removeEventListener('change',motion);mobile.removeEventListener('change',deviceChange);video.pause();video.removeAttribute('src');video.load();};}

let page='';function render(force=false){chrome();let hash=location.hash.slice(1)||'home';if(hash.startsWith('info/')){cleanup();page=hash;const names={ethics:['Etik İlkelerimiz','Ethical principles'],references:['Referanslar','References'],team:['Kadromuz','Our team'],privacy:['KVKK Aydınlatma Metni','Privacy notice'],security:['Bilgi Güvenliği Politikası','Information security policy'],cookies:['Çerez Politikası','Cookie policy']};const name=names[hash.slice(5)]||['Bilgi','Information'];main.innerHTML=`<article class="wrap article"><a href="#corporate">← ${text[lang].back}</a><h1>${name[lang==='tr'?0:1]}</h1><p>${lang==='tr'?'Bu konuda güncel bilgi ve belge talebinizi e-posta ile iletebilirsiniz.':'Please email us to request current information and documentation on this subject.'}</p><a class="btn" href="mailto:info@inovakademi.com">info@inovakademi.com ↗</a></article>`;window.scrollTo(0,0);return;}if(hash.startsWith('event/')){cleanup();cleanup=()=>{};page=hash;const eventIndex=Number(hash.slice(6));const t=text[lang];if(!Number.isInteger(eventIndex)||eventIndex<0||eventIndex>=t.eventTitles.length){main.innerHTML=`<div class="wrap article"><h1>${t.notFound}</h1><a href="#events">${t.back}</a></div>`;}else{main.innerHTML=`<article class="wrap article"><a class="back" href="#events">← ${lang==='tr'?'Takvime dön':'Back to calendar'}</a><p class="eyebrow">${t.eventTypes[eventIndex]}</p><h1>${t.eventTitles[eventIndex]}</h1><p class="article-meta">${['15','22','05','19','03','17'][eventIndex]} ${t.eventDates[eventIndex]} · ${t.example}</p><p class="intro">${t.eventBodies[eventIndex]}</p><section><h2>${lang==='tr'?'Program hakkında':'About this programme'}</h2><p>${t.eventsNote}</p><p>${lang==='tr'?'İçerik, katılımcıların deneyimine ve kurumun ihtiyacına göre planlanabilir. Bu sayfa üzerinden kayıt veya ödeme alınmaz.':'The content can be adapted to participants’ experience and organisational needs. This page does not accept registration or payment.'}</p></section><a class="btn" href="#contact">${t.talk} ↗</a></article>`;document.title=t.eventTitles[eventIndex]+' | İnovakademi';}window.scrollTo(0,0);document.querySelector('#navlinks').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');return;}if(hash.startsWith('article/')){cleanup();cleanup=()=>{};let a=articles.find(a=>a.id===hash.slice(8));page=hash;if(!a){main.innerHTML=`<div class="wrap article"><h1>${text[lang].notFound}</h1><a href="#home">${text[lang].back}</a></div>`;return;}let x=a[lang],count=[x.intro,...x.sections.flat()].join(' ').split(/\s+/).length;main.innerHTML=`<article class="wrap article"><a class="back" href="#insights">← ${text[lang].back}</a><p class="eyebrow">${x.tag}</p><h1>${x.title}</h1><span class="article-meta">${Math.max(3,Math.ceil(count/180))} ${text[lang].minutes}</span><p class="intro">${x.intro}</p>${x.sections.map(s=>`<section><h2>${s[0]}</h2>${s.slice(1).map(v=>`<p>${v}</p>`).join('')}</section>`).join('')}<div class="article-end">${articles.filter(z=>z.id!==a.id).map(z=>`<a class="back" href="#article/${z.id}">${z[lang].title} ↗</a>`).join('')}</div></article>`;document.title=x.title+' | İnovakademi';window.scrollTo(0,0);}else{if(page!=='home'||force){cleanup();renderHome();page='home';}document.title='İnovakademi — '+text[lang].footer;requestAnimationFrame(()=>{const section=document.getElementById(hash);if(section)section.scrollIntoView({behavior:'instant'});else if(hash==='home')window.scrollTo(0,0);});}document.querySelector('#navlinks').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');}
document.querySelector('#language').onclick=()=>{lang=lang==='tr'?'en':'tr';try{localStorage.setItem('ino-lang',lang);}catch(e){}render(true);};document.querySelector('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';try{localStorage.setItem('ino-theme',theme);}catch(e){}applyTheme();};document.querySelector('#menu').onclick=()=>{let open=document.querySelector('#navlinks').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open));document.querySelector('#menu').textContent=open?text[lang].close:text[lang].menu;};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#navlinks').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');document.querySelector('#menu').textContent=text[lang].menu;}});
