// Reading progress applies only to an open article.
const readingProgress=document.createElement('div');
readingProgress.className='reading-progress';
readingProgress.setAttribute('aria-hidden','true');
document.body.appendChild(readingProgress);
let readingFrame=0;
function updateReadingProgress(){readingFrame=0;const article=document.querySelector('article.article');if(!article){readingProgress.style.transform='scaleX(0)';return;}const start=article.getBoundingClientRect().top+window.scrollY;const distance=article.offsetHeight-window.innerHeight;const value=distance>0?Math.min(1,Math.max(0,(window.scrollY-start)/distance)):1;readingProgress.style.transform='scaleX('+value+')';}
function queueReadingProgress(){if(!readingFrame)readingFrame=requestAnimationFrame(updateReadingProgress);}
window.addEventListener('scroll',queueReadingProgress,{passive:true});
window.addEventListener('resize',queueReadingProgress);
window.addEventListener('hashchange',queueReadingProgress);
new MutationObserver(queueReadingProgress).observe(document.querySelector('main'),{childList:true});
queueReadingProgress();

