function podcastMarkup(){const label=bilingual;return `<div class="podcast-feature"><div><img class="spotify-logo" src="spotify-logo.png" alt="Spotify"><span class="eyebrow">${label('İNOVAKADEMİ PODCAST','İNOVAKADEMİ PODCAST')}</span><h2>${label('Yeni bir bakış açısına kulak verin','Listen to a new perspective')}</h2><p>${label('Okumaya kısa bir ara verin. İnovakademi podcastine kulak verin, bölümlere göz atın ve dinlemeye Spotify’da devam edin.','Take a break from reading. Explore the İnovakademi podcast, browse episodes and keep listening on Spotify.')}</p><a class="podcast-link" href="${podcastURL}" target="_blank" rel="noopener">${label('Spotify’da dinleyin','Listen on Spotify')} ↗</a></div><div class="podcast-player"><iframe title="İnovakademi Spotify podcast" src="https://open.spotify.com/embed/show/0eaaf47GkBfMlar8ruQ56o?utm_source=generator&theme=0" width="100%" height="352" frameborder="0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe><small>${label('Oynatıcı açılmazsa Spotify’da dinleyin bağlantısını kullanabilirsiniz','If the player is unavailable, use the Listen on Spotify link')}</small></div></div>`;}

const corporateData={"tr": {"vision": [["Vizyonumuz", "KOBİ’lerin dijitalleşme, sürdürülebilirlik ve yapay zeka odaklı dönüşümüne yön veren lider marka olmak.", "Yenilikçi yaklaşımlar, güçlü networking ağları ve küresel pazarda rekabet avantajı sağlayan çözümlerle kurumları geleceğe taşıyoruz.", "İnovakademi’nin vizyonu, SKDM ve yeşil dönüşüm süreçlerinde KOBİ’lere rehberlik eden, değer odaklı ve güvenilir bir eğitim ve danışmanlık markası olmaktır."], ["Misyonumuz", "Teknoloji, sürdürülebilirlik ve küresel pazara entegrasyon odaklı gelişim yolculuğu.", "KOBİ’lerin değişen ihtiyaçlarına yanıt veren dijital yetkinlikler, stratejik networking ve heyet organizasyonlarını kapsayan bütünsel çözümler sunuyoruz.", "Sınırda Karbon Düzenleme Mekanizması (SKDM) uyumu, yapay zeka destekli içerikler ve yenilikçi yaklaşımlar ile bireylere ve kurumlara uluslararası ölçekte değer katıyoruz."], ["Değerlerimiz", "Etik ve Güvenilirlik – Her koşulda şeffaflık ve sorumlulukla hareket ederiz.", "Yenilikçilik ve Teknoloji – Sürekli öğrenir, dijital çözümler üretir ve geliştiririz.", "Sürdürülebilirlik ve Büyüme – Çevresel etkileri gözetir, KOBİ’lerin küresel gelişimini destekleriz.", "Katılımcı ve İş Birliği Odaklılık – Ağ kurma ve heyet organizasyonlarıyla insan merkezli çözümler sunarız.", "Veriye Dayalı Karar – İçgörüyle yön veririz."]], "ethics": [["Kişisel Tercihler ve Bağımlılıklar", "İnovakademi, tüm bireylerin kişisel tercihlerine saygı duyar. Ancak iş ilişkilerinde profesyonellik esastır. Bu nedenle alkol, tütün, uyuşturucu ve benzeri bağımlılık yaratıcı maddeler hakkında konuşmak, ima etmek veya bu konularla ilgili içerik paylaşmak kurumsal ortamlarda kesinlikle yasaktır. Bu tercihler özel yaşama ait olup iş ortamında yeri yoktur."], ["Cinsel Yönelim ve Kimliklere Saygı", "Cinsel yönelim ve kimlikler kişisel alana girer. Bu konuların iş ortamında konuşulması, sorgulanması, ima edilmesi veya tartışma konusu yapılması etik dışıdır ve yasaktır. Her bireyin özel hayatına ve kimliğine saygı duymak, kapsayıcı bir çalışma kültürünün temelidir."], ["Siyasi Görüş ve Tartışmalardan Kaçınma", "İnovakademi, farklı siyasi görüşlere sahip bireylerin bir arada huzurlu ve verimli çalışmasını önemser. Bu doğrultuda, siyasi görüş bildirmek, siyasi içerikli tartışmalara girmek veya kurum içinde bu konuları gündeme getirmek yasaktır."], ["İş Dışı Sosyal Buluşmalar", "İş dışında gerçekleştirilen sosyal buluşmalar (çay, kahve, alkol, tiyatro, sinema vb.) bireylerin kendi özel tercihidir. Ancak bu buluşmaların iş ortamına taşınması, kurumsal kaynaklarla desteklenmesi veya bu tür etkinliklerin iş amaçlıymış gibi sunulması kabul edilmez. İnovakademi, sosyal etkinliklerin sınırlarını profesyonellik çerçevesinde belirler."], ["Üçüncü Şahıslarla İlgili Yorum Yapmama", "İnovakademi çalışanları, iş ortakları ve ilgili kurum personelleri hakkında dedikodu, yorum veya spekülatif değerlendirmelerde bulunmak kesinlikle yasaktır. Bu tür konuşmalar hem kişisel hakların ihlali hem de iş etiği açısından uygun değildir."], ["Hediye Politikası", "Çıkar çatışmasını önlemek adına hiçbir çalışan 30 USD (veya eşdeğeri) üzerinde hediye alamaz ya da veremez. Bu kural, tarafsızlık ve şeffaflık ilkesinin korunması için uygulanmaktadır. Özel günlerde sembolik değeri olan küçük hediyeler hariç tutulabilir, ancak yine de şeffaflık ilkesi gözetilmelidir."], ["Dürüstlük ve Şeffaflık", "Tüm çalışanlar, görevlerini yerine getirirken doğruluk, dürüstlük ve şeffaflık ilkeleri doğrultusunda hareket eder. Kurum içi ve dışı tüm iletişimde yanıltıcı bilgi verilmesi veya bilgi saklanması etik ihlaldir."], ["Çıkar Çatışmalarından Kaçınma", "Hiçbir çalışan, kişisel çıkarları ile İnovakademi’nin çıkarlarını çatışacak duruma getirecek eylemde bulunamaz. Akrabalık, arkadaşlık ya da başka ilişkiler nedeniyle alınacak kararlar nesnelliği zedelememelidir."], ["Gizlilik ve Bilgi Güvenliği", "Çalışanlar, İnovakademi’ye ait gizli bilgileri (mali veriler, projeler, müşteri bilgileri vb.) sadece kamu alanındaki yetkili kişilerle paylaşabilir. Kurum dışına bilgi aktarımı, açık yazılı onay olmadan kesinlikle yasaktır."], ["İnsan Haklarına ve Çeşitliliğe Saygı", "Irk, dil, din, cinsiyet, yaş, engellilik, etnik köken, siyasi görüş veya sosyal statü ayrımı yapılmaksızın her bireye eşit yaklaşılır. Ayrımcılık, taciz veya mobbing kurum kültürümüzle bağdaşmaz."], ["Yolsuzluk ve Rüşvetle Mücadele", "Her türlü yolsuzluk, zimmete geçirme, rüşvet teklif etme ya da kabul etme gibi davranışlar kesinlikle yasaktır. Bu tür fiiller, derhal Etik Kurul’a bildirilmelidir."], ["Kaynakların Etkin ve Amaca Uygun Kullanımı", "İnovakademi’ye ait tüm kaynaklar (zaman, ekipman, yazılım, bütçe vb.) yalnızca iş amaçlı kullanılmalı, kişisel fayda ya da dış projeler için tahsis edilmemelidir."], ["Sosyal Medya ve Dijital Temsil", "Çalışanlar, sosyal medya paylaşımlarında İnovakademi’nin itibarına zarar verebilecek yorum ve içeriklerden kaçınmalıdır. Şirketle ilişkilendirilebilecek her dijital davranışta sorumluluk bilinciyle hareket edilmelidir."], ["Etik İhlal Bildirim Yükümlülüğü", "Etik kurallara aykırı bir davranışla karşılaşan her çalışan, durumu yöneticisine veya Etik Kurul’a bildirmekle yükümlüdür. Bildirim yapan çalışanlar, hiçbir şekilde baskıya maruz bırakılamaz veya cezalandırılamaz."], ["Etik Kurul ve Denetim", "Etik kuralların uygulanmasını izlemek ve ihlalleri değerlendirmek amacıyla bağımsız bir Etik Kurul oluşturulmuştur. Kurul, şikâyetleri tarafsız biçimde inceleyerek gerekli yaptırımları uygular."]], "application": [["Etik Kurul Başvuru Bilgilendirmesi", "İnovakademi, tüm faaliyetlerinde etik değerlere, şeffaflığa ve adil yaklaşıma öncelik verir. Bu doğrultuda, etik ilkelere aykırı bir durumla karşılaşan veya gözlemleyen tüm çalışanlarımız, iş ortaklarımız ve üçüncü taraf paydaşlarımız, Etik Kurul’a başvuruda bulunma hakkına sahiptir."], ["Etik Kurul’a Nasıl Başvurulur?", "Etik Kurul’a yapılacak başvurular e-posta ile doğrudan iletilebilir. Bireysel veya grup iletişimi kabul edilir."], ["Başvuru Metninizde Bulunması Önerilen Bilgiler", "Gözlemlediğiniz etik dışı durumun kısa özeti", "Olayın yeri ve zamanı (varsa tanıklar)", "Kişisel bilginizi paylaşmak istemiyorsanız, anonim başvuru da yapabilirsiniz", "Belgeler veya ekran görüntüsü gibi kanıtlayıcı materyaller (varsa)"], ["Gizlilik Taahhüdü", "Tüm başvurular gizlilikle değerlendirilir. Hiçbir çalışan ya da paydaş, yaptığı etik başvuru nedeniyle doğrudan veya dolaylı şekilde zarar görmez, baskı altına alınamaz."]], "references": ["Doğu Karadeniz İhracatçılar Birliği", "Doğanlar Mobilya Grubu İmalat San. ve Tic. A.Ş.", "Düzce Ticaret Borsası", "Easyvit Sağlık Ürünleri Sanayi Anonim Şirketi", "Ece Global Lojistik İç ve Dış Ticaret A.Ş.", "Eda Işıl Alp", "Edremit Ticaret Odası", "Ege İhracatçılar Birliği", "Ekin Zeytincilik", "ERTEKS Kadife Tekstil Sanayi ve Ticaret Limited Şirketi", "Eskişehir Sanayi Odası", "Eskişehir Ticaret Odası", "Evyap", "Fındık ve Mamulleri İhracatçıları Birliği", "Fill Yazılım ve Danışmanlık Hizmetleri Anonim Şirketi", "Gamak Makina Sanayi Anonim Şirketi", "Gazi Teknokent", "Gaziantep Sanayi Odası", "Gaziantep Üniversitesi", "Gaziantep Genç İş Adamları Derneği", "Goldman Sachs 10000 Kadın Girişimci Projesi", "Göreme Melamin Plastik San. Dış Tic. Ltd. Şti.", "Günsan Elektrik Malzemeleri San. Tic. A.Ş.", "GAİB – Güneydoğu Anadolu İhracatçı Birlikleri", "Hizmet İhracatçıları Birliği", "IC Holding", "İİB – İstanbul İhracatçılar Birliği", "İkitelli OSB", "İMMİB – İstanbul Maden İhracatçıları Birliği", "İpekyolu Kalkınma Ajansı", "İDDMİB – İstanbul Demir ve Demir Dışı Metal İhracatçıları Birliği", "İstanbul Hububat Bakliyat Yağlı Tohumlar ve Mamulleri İhracatçı Birliği", "İstanbul Kimyevi Maddeler ve Mamulleri İhracatçıları Birliği", "İstanbul Mobilya Kağıt ve Orman Ürünleri İhracatçıları Birliği", "İstanbul Sanayi Odası", "İskenderun Ticaret ve Sanayi Odası", "İTB – İzmir Ticaret Odası", "Kahramanmaraş Ticaret ve Sanayi Odası", "Kapı Sistemleri Mümessillik Ltd. Şti.", "KAGİDER – Kadın Girişimcileri Derneği", "Kayseri Ticaret Odası", "Kemal Balıkçılık İhr. Ltd. Şti.", "Kırmızıgül Kozmetik ve Turizm San. Tic. Ltd. Şti.", "Klimasan Klima Sanayi ve Ticaret Anonim Şirketi", "Koç Üniversitesi Hastanesi", "KTO – Konya Ticaret Odası", "KOSGEB", "1K Kimya A.Ş.", "Likya Otelleri", "Malatya Ticaret ve Sanayi Odası", "Mardin Organize Sanayi Bölgesi", "Martaş Oto Yedek Parça Tic. Ve San. A.Ş.", "Mersin Teknokent", "Mersin Ticaret ve Sanayi Odası", "Mora Cam Sanayi ve Ticaret Anonim Şirketi", "Multigrain Tarım Ürünleri Gıda Sana. ve Tic. Ano. Şti.", "Mücevher İhracatçı Birliği", "McCormick Kütaş Gıda Sanayi Dış Ticaret A.Ş.", "Nitto Bento Bantçılık Sanayi ve Tic. A.Ş.", "Nizip Ticaret Odası", "Nidec Endüstriyel Kontrol Sistemleri Sanayi Ve Ticaret Anonim Şirketi", "Ode Yalıtım", "OMSİAD", "OSTİM – Organize Sanayi Bölgesi", "Pamukkale Teknopark", "Sakarya Üniversitesi", "SAMİB – Sakarya Makine İmalatçıları Birliği", "SATSO – Sakarya Ticaret ve Sanayi Odası", "Saha İstanbul – Savunma Havacılık ve Uzay Kümelenmesi", "Servet Şekerleme Gıda Turizm Sanayi ve Ticaret Anonim Şirketi", "Sima Group Tekstil Sanayi Ticaret Ltd. Şti.", "Şişecam", "Toprak Zeytin Z.Yağı Gıda Tarım Ürün Hayv San. ve Tic. Ltd. Şti.", "TOBB Kadın Girişimciler Kurulu", "TSUAB – Tohum Sanayicileri ve Üreticileri Alt Birliği", "TİM – Türkiye İhracatçılar Meclisi", "Trabzon Ticaret ve Sanayi Odası", "Uludağ İhracatçı Birlikleri", "Usluoğlu Makina Kalıp ve Plastik Ltd. Şti.", "Welfar Central İlaç Anonim Şirketi", "Yiğiter Orman Ürünleri İnş. Paz. San. Tic. Ltd. Şti.", "7020 Mimarlık İth. İhr. Dış Tic. A.Ş."]}, "en": {"vision": [["Our vision", "To be a leading brand guiding SMEs through digitalisation, sustainability and AI-driven transformation.", "We help organisations move forward through innovative approaches, strong networking and solutions that support competitiveness in global markets.", "İnovakademi aims to be a trusted, value-focused training and consulting brand guiding SMEs through CBAM and green transformation."], ["Our mission", "A development journey focused on technology, sustainability and integration into global markets.", "We offer integrated solutions covering digital capabilities, strategic networking and business delegations that respond to SMEs’ changing needs.", "Through CBAM alignment, AI-supported content and innovative approaches, we create value for people and organisations internationally."], ["Our values", "Ethics and reliability – We act transparently and responsibly in all circumstances.", "Innovation and technology – We keep learning, creating and improving digital solutions.", "Sustainability and growth – We consider environmental impacts and support the global development of SMEs.", "Participation and collaboration – We offer people-centred solutions through networking and delegations.", "Data-based decisions – We guide through insight."]], "ethics": [["Personal choices and addictions", "İnovakademi respects individual personal choices. Professionalism is essential in business relationships. Discussing, implying or sharing content about alcohol, tobacco, drugs and similar addictive substances is strictly prohibited in corporate settings. Such choices belong to private life and have no place in the workplace."], ["Respect for sexual orientation and identity", "Sexual orientation and identity are personal matters. Discussing, questioning, implying or debating them in the workplace is unethical and prohibited. Respect for each person’s private life and identity is fundamental to an inclusive working culture."], ["Avoiding political discussions", "İnovakademi values peaceful and productive collaboration between people with different political views. Expressing political views, entering political debates or raising these topics within the organisation is prohibited."], ["Social meetings outside work", "Social meetings outside work, including tea, coffee, alcohol, theatre or cinema, are personal choices. Bringing these meetings into the workplace, supporting them with corporate resources or presenting them as business activities is not acceptable. İnovakademi sets professional boundaries for social activities."], ["No commentary about third parties", "Gossip, commentary or speculative assessments about İnovakademi employees, business partners or associated staff are strictly prohibited. Such conversations infringe personal rights and are incompatible with professional ethics."], ["Gift policy", "To avoid conflicts of interest, employees may not accept or give gifts worth more than USD 30 or equivalent. This rule protects impartiality and transparency. Small symbolic gifts on special occasions may be exempt, while transparency must still be maintained."], ["Honesty and transparency", "All employees perform their duties in line with accuracy, honesty and transparency. Giving misleading information or concealing information in internal or external communication is an ethical violation."], ["Avoiding conflicts of interest", "Employees may not act in ways that place personal interests in conflict with İnovakademi’s interests. Decisions influenced by family, friendship or other relationships must not undermine objectivity."], ["Confidentiality and information security", "Employees may share confidential İnovakademi information, including financial data, projects and customer details, only with authorised persons in the public sphere. Transfer of information outside the organisation without explicit written approval is strictly prohibited."], ["Respect for human rights and diversity", "Everyone is treated equally without distinction based on race, language, religion, gender, age, disability, ethnic origin, political views or social status. Discrimination, harassment and workplace bullying are incompatible with our culture."], ["Combating corruption and bribery", "Corruption, embezzlement and offering or accepting bribes are strictly prohibited. Such conduct must be reported immediately to the Ethics Board."], ["Effective and appropriate use of resources", "All İnovakademi resources, including time, equipment, software and budgets, must be used only for business purposes and must not be allocated to personal benefit or outside projects."], ["Social media and digital representation", "Employees must avoid social media comments or content that could damage İnovakademi’s reputation. All digital behaviour associated with the company must reflect responsibility."], ["Duty to report ethical violations", "Every employee who encounters a violation must report it to their manager or the Ethics Board. Employees who report concerns must not face pressure or punishment."], ["Ethics Board and oversight", "An independent Ethics Board has been established to monitor implementation and assess violations. The Board reviews complaints impartially and applies necessary sanctions."]], "application": [["Ethics Board application information", "İnovakademi prioritises ethical values, transparency and fairness. All employees, business partners and third-party stakeholders who experience or observe an ethical violation may apply to the Ethics Board."], ["How to contact the Ethics Board", "Applications can be sent directly by email. Individual and group communications are accepted."], ["Recommended information for your application", "A brief summary of the observed concern", "The place and time of the incident, including witnesses if any", "You may apply anonymously if you do not wish to share your identity", "Supporting material such as documents or screenshots, if available"], ["Confidentiality commitment", "All applications are reviewed confidentially. No employee or stakeholder may suffer direct or indirect harm or pressure because of an ethical report."]]}};

const projectTitles=['Turkish Pharma Cluster · 19.UR-GE.040','Doğaltaş · 18.UR-GE.025','Turkish Animal Pro · 19.UR-GE.035','ATSO Tarım Kümesi'];
function searchableRail(){return `<aside class="blog-rail"><form class="blog-search" role="search"><label for="blog-search-input">${bilingual('Yazılarda ara','Search articles')}</label><div><input id="blog-search-input" type="search" placeholder="${bilingual('Konu veya kelime','Topic or keyword')}"><button aria-label="${bilingual('Ara','Search')}" type="submit">⌕</button></div></form><h3>${bilingual('Blog yazıları','Blog articles')}</h3><div class="rail-results">${articles.map(a=>`<a href="#article/${a.id}"><span><small>${a[lang].tag}</small><strong>${a[lang].title}</strong></span><span>↗</span></a>`).join('')}</div><p class="rail-status" role="status"></p></aside>`;}
function bindSearch(){document.querySelectorAll('.blog-search').forEach(form=>{const input=form.querySelector('input'),rail=form.closest('aside');const search=()=>{const q=input.value.trim().toLocaleLowerCase(lang);const found=articles.filter(a=>[a[lang].title,a[lang].intro,...a[lang].sections.flat()].join(' ').toLocaleLowerCase(lang).includes(q));rail.querySelector('.rail-results').innerHTML=found.map(a=>`<a href="#article/${a.id}"><span><small>${a[lang].tag}</small><strong>${a[lang].title}</strong></span><span>↗</span></a>`).join('');rail.querySelector('.rail-status').textContent=found.length?`${found.length} ${bilingual('yazı','articles')}`:bilingual('Sonuç bulunamadı','No results found');};input.oninput=search;form.onsubmit=e=>{e.preventDefault();search();};});}
function contentSections(items,numbered=false){return items.map((x,i)=>`<section class="policy-section"><h2>${numbered?'<span class="policy-number">'+String(i+1).padStart(2,'0')+'</span>':''}${x[0]}</h2>${x.slice(1).map(t=>`<p>${t}</p>`).join('')}</section>`).join('');}
function gallery(){return `<section class="work-gallery"><h2>${bilingual('Çalışma örnekleri','Selected work')}</h2><div class="work-grid">${projectTitles.map((title,i)=>`<a href="project-${i+1}.png" target="_blank" rel="noopener"><img src="project-${i+1}.png" alt="${title}" loading="lazy" decoding="async"><span>${title} ↗</span></a>`).join('')}</div></section>`;}
const previousRender=render;
render=function(force=false){const route=location.hash.slice(1);const type={'vision':'vision','info/ethics':'ethics','info/references':'references'}[route];
if(type){cleanup();cleanup=()=>{};page=route;chrome();const data=corporateData[lang];let body='',title='';
if(type==='vision'){title=bilingual('Vizyon & Misyon','Vision & mission');body=contentSections(data.vision);}
if(type==='ethics'){title=bilingual('Etik İlkelerimiz','Our ethical principles');body=contentSections(data.ethics,true)+contentSections(data.application.slice(0,2))+`<section class="ethics-contact"><h2>${bilingual('Bağımsız Etik Kurul Üyeleri','Independent Ethics Board members')}</h2><p>Varol ÜNEL: <a href="mailto:vunel@inovakademi.com">vunel@inovakademi.com</a></p><p>Ufuk ÖZÇELİK: <a href="mailto:uozcelik@inovakademi.com">uozcelik@inovakademi.com</a></p></section>`+contentSections(data.application.slice(2));}
if(type==='references'){title=bilingual('Referanslarımız','Our references');body=`<ul class="reference-list">${corporateData.tr.references.map(n=>`<li>${n}</li>`).join('')}</ul>${gallery()}`;}
main.innerHTML=`<div class="wrap section document-layout"><article class="document-copy"><h1>${title}</h1>${body}</article>${searchableRail()}</div>`;document.title=title+' | İnovakademi';enhanceSite();window.scrollTo(0,0);
}else{previousRender(force);document.querySelectorAll('.blog-rail').forEach(rail=>rail.outerHTML=searchableRail());}
if(page==='corporate'&&!document.querySelector('.document-layout')){const copy=main.querySelector('.corporate-page');if(copy){const layout=document.createElement('div');layout.className='wrap section document-layout';copy.classList.remove('wrap','section');copy.replaceWith(layout);layout.append(copy);layout.insertAdjacentHTML('beforeend',searchableRail());}}bindSearch();document.querySelector('#navlinks').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');
};
render(true);
